private string HtmlEncodeText(string strText)
{
    if (strText == null || strText.Length == 0)
        return "&nbsp;";
    return strText.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;").Replace("\"", "&quot;");
}

private string GetDataRowText(DataRow drw, string strField)
{
    if (drw == null || !drw.Table.Columns.Contains(strField) || drw[strField] == DBNull.Value)
        return "";
    return Convert.ToString(drw[strField]);
}

private string FormatMarkHtml(object objValue, string strFormat, bool bolFail)
{
    if (objValue == null || objValue == DBNull.Value)
        return "<td>&nbsp;</td>";

    string strRaw = Convert.ToString(objValue);
    if (strRaw.Length < 1)
        return "<td>&nbsp;</td>";
    if (strRaw == "-1")
        return "<td>M</td>";

    string strValue = strRaw;
    try
    {
        double dbl = Convert.ToDouble(objValue);
        System.Globalization.CultureInfo cul = new System.Globalization.CultureInfo("vi-VN");
        strValue = dbl.ToString(strFormat, cul);
    }
    catch
    {
        strValue = HtmlEncodeText(strRaw);
    }

    if (bolFail)
        return "<td class='fail'>" + strValue + "</td>";
    return "<td>" + strValue + "</td>";
}

private bool IsMarkFailed(DataRow drw, int intIndex)
{
    string strPassCol = "Passed_" + intIndex.ToString();
    if (drw.Table.Columns.Contains(strPassCol) && drw[strPassCol] != DBNull.Value && Convert.ToString(drw[strPassCol]) != "")
    {
        try
        {
            return !Convert.ToBoolean(drw[strPassCol]);
        }
        catch
        {
            return false;
        }
    }
    return false;
}

