private string BuildVerticalHeaderCell(string strCaption, bool bolBold, int intRowSpan, int intColSpan)
{
    string strAttr = "";
    if (intRowSpan > 1)
        strAttr += " rowspan='" + intRowSpan.ToString() + "'";
    if (intColSpan > 1)
        strAttr += " colspan='" + intColSpan.ToString() + "'";
    string strStyle = bolBold ? " style='font-weight:bold;'" : "";
    return "<th class='subject-name'" + strAttr + strStyle + ">" + HtmlEncodeText(strCaption) + "</th>";
}

