    if (iSoMon >= 5)
        return 12;
    return 15;
}

private string FormatStatPercent(double dblCount, double dblTotal)
{
    if (dblTotal < 1)
        return "0";
    double dbl = Math.Round(dblCount * 100.0 / dblTotal, 2);
    System.Globalization.CultureInfo cul = new System.Globalization.CultureInfo("vi-VN");
    return dbl.ToString("0.##", cul);
}

private string BuildTongKetStatisticHtml(DataTable dtbSource)
{
    double iTB = 0;
    double iKha = 0;
    double iTot = 0;
    double iXuatSac = 0;
    double iSV = 0;
    double iYeu = 0;

    for (int j = 0; j < dtbSource.Rows.Count; j++)
    {
        iSV += 1;
        string strLevel = Convert.ToString(dtbSource.Rows[j]["LearningLevel"]);
        if (strLevel == "Yếu" || strLevel == "Kém" || strLevel == "Yếu kém")
            iYeu += 1;
        else if (strLevel == "Trung bình" || strLevel == "TB khá")
            iTB += 1;
        else if (strLevel == "Khá")
            iKha += 1;
        else if (strLevel == "Giỏi")
            iTot += 1;
        else if (strLevel == "Xuất sắc")
            iXuatSac += 1;
    }

    StringBuilder sb = new StringBuilder();
    sb.Append("<table class='stat-table'>");
    sb.Append("<tr><th>Xếp loại</th><th>SL</th><th>Tỉ lệ</th><th>Xếp loại</th><th>SL</th><th>Tỉ lệ</th></tr>");
    sb.Append("<tr><td>Xuất sắc</td><td>").Append(iXuatSac.ToString("0")).Append("</td><td>")
        .Append(FormatStatPercent(iXuatSac, iSV)).Append("</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr>");
    sb.Append("<tr><td>Giỏi</td><td>").Append(iTot.ToString("0")).Append("</td><td>")
        .Append(FormatStatPercent(iTot, iSV)).Append("</td><td>TB</td><td>")
        .Append(iTB.ToString("0")).Append("</td><td>").Append(FormatStatPercent(iTB, iSV)).Append("</td></tr>");
    sb.Append("<tr><td>Khá</td><td>").Append(iKha.ToString("0")).Append("</td><td>")
        .Append(FormatStatPercent(iKha, iSV)).Append("</td><td>Yếu</td><td>")
        .Append(iYeu.ToString("0")).Append("</td><td>").Append(FormatStatPercent(iYeu, iSV)).Append("</td></tr>");
    sb.Append("</table>");
    return sb.ToString();
}

private string BuildTongKetFooterHtml(DataTable dtbSource, string strPrintDate)
