private string LoadHtmlTemplate(string strRelativePath, string strFallbackTitle)
{
    string[] arrPaths = new string[] {
        Application.StartupPath + "\\" + strRelativePath,
        Application.StartupPath + "\\..\\..\\" + strRelativePath,
        Application.StartupPath + "\\..\\..\\..\\" + strRelativePath
    };

    for (int i = 0; i < arrPaths.Length; i++)
    {
        try
        {
            string strFull = System.IO.Path.GetFullPath(arrPaths[i]);
            if (System.IO.File.Exists(strFull))
                return System.IO.File.ReadAllText(strFull, Encoding.UTF8);
        }
        catch
        {
        }
    }

    StringBuilder sb = new StringBuilder();
    sb.Append("<!DOCTYPE html><html><head><meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />");
    sb.Append("<title>").Append(strFallbackTitle).Append("</title>");
    sb.Append("<style type=\"text/css\">body{font-family:'Times New Roman',Times,serif;font-size:11pt;margin:10px;}");
    sb.Append("table{border-collapse:collapse;}.mark-table th,.mark-table td{border:1px solid #000;padding:2px 3px;text-align:center;}");
    sb.Append(".fail{background-color:#FFFF99;}</style></head><body>{CONTENT}</body></html>");
    return sb.ToString();
}

private void SaveAndOpenHtml(string strFileName, string strContent)
{
    string strExportDir = Application.StartupPath + "\\Export";
    if (!System.IO.Directory.Exists(strExportDir))
        System.IO.Directory.CreateDirectory(strExportDir);

    string strClass = uClass.ClassName;
    if (strClass == null || strClass.Length < 1)
        strClass = Convert.ToString(uClass.ClassIDEditValue);
    strClass = strClass.Replace("\\", "_").Replace("/", "_").Replace(":", "_");

    string strFilePath = strExportDir + "\\" + strClass + "_" + strFileName;
    System.IO.File.WriteAllText(strFilePath, strContent, Encoding.UTF8);
    System.Diagnostics.Process.Start(strFilePath);
}

/// <summary>
/// Xuất HTML - Bảng điểm tổng kết (cấu trúc giống Leaning_BangDiem_HocKyLC_xQC09 / HocKy_xQC09).
/// Dữ liệu truyền y như report cũ: dtbData trên lưới + dtbClassSubject.
/// </summary>
private void ExportBangDiemTongKet_HTML()
{
    try
    {
        if (dtbData == null || dtbClassSubject == null || dtbClassSubject.Rows.Count < 1)
        {
            MessageManager.Warning("Không có dữ liệu để xuất!");
            return;
        }

        DataTable dtbSource = dtbData;
        if (gvData.DataSource is DataView)
            dtbSource = (gvData.DataSource as DataView).Table;
        if (dtbSource == null || dtbSource.Rows.Count < 1)
        {
            MessageManager.Warning("Không có dữ liệu để xuất!");
            return;
        }

        DateTime dtmNow = SystemService.SYS_SettingService.CurrentDateTime;
        string strPlace = strReport_Place;
        if (strPlace == null || strPlace.Length < 1)
            strPlace = SystemService.SYS_SettingService.GetStringValue("Report_Place");
        if (strPlace == null || strPlace.Length < 1)
            strPlace = "Tp. Hồ Chí Minh";
        string strPrintDate = strPlace
            + ", ngày " + dtmNow.Day.ToString()
            + " tháng " + dtmNow.Month.ToString()
            + " năm " + dtmNow.Year.ToString();

        string strNote = "(Lấy kết quả điểm kiểm tra, điểm tổng kết môdun/môn học lần cuối)";
        if (chkViewOnlyExam1.Checked)
            strNote = "(Lấy kết quả điểm kiểm tra, điểm tổng kết môdun/môn học lần 1)";

        string strSubtitle = "NĂM HỌC " + uYearSemester.YearEditValueText;
        if (uYearSemester.SemesterEditValue != null)
            strSubtitle = "HỌC KÌ " + Convert.ToString(uYearSemester.SemesterEditValue) + " NĂM HỌC " + uYearSemester.YearEditValueText;

        int intRowsPerPage = GetHtmlTongKetRowsPerPage();
        int intTotal = dtbSource.Rows.Count;
        int intPageCount = (intTotal + intRowsPerPage - 1) / intRowsPerPage;
        string strTableHeader = BuildTongKetMarkTableHeaderHtml();

        StringBuilder sb = new StringBuilder();
        for (int intPage = 0; intPage < intPageCount; intPage++)
        {
            bool bolLastPage = (intPage == intPageCount - 1);
            bool bolFirstPage = (intPage == 0);
            sb.Append("<div class='print-page").Append(bolLastPage ? " last-page" : "").Append("'>");

            if (bolFirstPage)
            {
                sb.Append(BuildHtmlHeaderBlock());
                sb.Append("<div class='title'>BẢNG TỔNG KẾT KẾT QUẢ HỌC TẬP</div>");
                sb.Append("<div class='subtitle'>").Append(HtmlEncodeText(strSubtitle)).Append("</div>");
                sb.Append("<div class='note'>").Append(HtmlEncodeText(strNote)).Append("</div>");
                sb.Append(BuildTongKetInfoBlockHtml());
            }

            sb.Append("<table class='mark-table'>");
            sb.Append(BuildTongKetMarkTableColGroupHtml());
            sb.Append(strTableHeader);
            sb.Append("<tbody>");

            int intFrom = intPage * intRowsPerPage;
            int intTo = intFrom + intRowsPerPage;
            if (intTo > intTotal)
                intTo = intTotal;

            for (int r = intFrom; r < intTo; r++)
            {
                DataRow drw = dtbSource.Rows[r];
                int intSTT = r + 1;
                sb.Append("<tr>");
                sb.Append("<td class='col-tt'>").Append(intSTT.ToString()).Append("</td>");
                sb.Append("<td class='col-code'>").Append(HtmlEncodeText(GetDataRowText(drw, "StudentCode"))).Append("</td>");
                sb.Append("<td class='name-left'>").Append(HtmlEncodeText(GetDataRowText(drw, "StudentFirstName"))).Append("</td>");
                sb.Append("<td class='name-right'>").Append(HtmlEncodeText(GetDataRowText(drw, "StudentLastName"))).Append("</td>");
                sb.Append(BuildTongKetStudentMarkCells(drw));

                object objTbc10 = drw.Table.Columns.Contains("SummaryLearningMark10") ? drw["SummaryLearningMark10"] : null;
                string strTbc10 = FormatMarkHtml(objTbc10, "0.0", false);
                strTbc10 = strTbc10.Replace("<td>", "<td><b>").Replace("</td>", "</b></td>");
                sb.Append(strTbc10);

                object objTbc4 = drw.Table.Columns.Contains("SummaryLearningMark") ? drw["SummaryLearningMark"] : null;
                string strTbc4 = FormatMarkHtml(objTbc4, "0.00", false);
                strTbc4 = strTbc4.Replace("<td>", "<td><b>").Replace("</td>", "</b></td>");
                sb.Append(strTbc4);

                object objDebt = drw.Table.Columns.Contains("SomeDebt") ? drw["SomeDebt"] : null;
                sb.Append(FormatMarkHtml(objDebt, "0", false));

                sb.Append("<td>").Append(HtmlEncodeText(GetDataRowText(drw, "LearningLevel"))).Append("</td>");

                object objEthic = drw.Table.Columns.Contains("EthicMark") ? drw["EthicMark"] : null;
                sb.Append(FormatMarkHtml(objEthic, "0.0", false));
                sb.Append("<td>").Append(HtmlEncodeText(GetDataRowText(drw, "EthicLevel"))).Append("</td>");
                sb.Append("</tr>");
            }

            sb.Append("</tbody></table>");

            if (bolLastPage)
                sb.Append(BuildTongKetFooterHtml(dtbSource, strPrintDate));

            sb.Append("</div>");
        }

        string strTemplate = LoadHtmlTemplate("MauHtml\\BangDiem\\BangDiem_TongKet.htm", "Bảng tổng kết kết quả học tập");
        string strFileContent = strTemplate.Replace("{CONTENT}", sb.ToString());
        SaveAndOpenHtml("BangDiem_TongKet.htm", strFileContent);
    }
    catch
    {
        ErrorManager.Error("Dữ liệu chưa hợp lệ để xuất HTML!");
    }
}

