private List<int> BuildTongKetPageStarts(int intTotal)
{
    List<int> lst = new List<int>();
    lst.Add(0);

    int intFirst = GetHtmlTongKetFirstPageRows();
    int intNext = GetHtmlTongKetNextPageRows();

    if (intTotal <= intFirst)
        return lst;

    int intPos = intFirst;
